// ═══ SEED FUNCTION ═══
async function main() {
  await mongoose.connect(MONGODB_URI);
  console.log("Connected to MongoDB");

  const db = mongoose.connection.db;
  const collection = db.collection("interactivecourses");

  const existing = await collection.findOne({ slug: COURSE_DATA.slug });
  if (existing) {
    await collection.updateOne({ slug: COURSE_DATA.slug }, { $set: COURSE_DATA });
    console.log("✓ Updated:", COURSE_DATA.title);
  } else {
    COURSE_DATA.createdAt = new Date();
    COURSE_DATA.updatedAt = new Date();
    await collection.insertOne(COURSE_DATA);
    console.log("✓ Created:", COURSE_DATA.title);
  }

  // ─── VALIDATION STATS ───
  let totalWords = 0;
  let totalBlocks = 0;
  let kcs = 0;
  let reflections = 0;
  let interactives = 0;
  let examQs = 0;
  const sectionStats = [];

  for (const section of COURSE_DATA.sections) {
    let sectionWords = 0;
    let sectionKCs = 0;
    for (const block of section.contentBlocks) {
      totalBlocks++;
      if (block.type === "text" || block.type === "imageText") {
        const text = (block.content || "").replace(/<[^>]+>/g, " ");
        const wc = text.split(/\s+/).filter(w => w).length;
        totalWords += wc;
        sectionWords += wc;
      }
      if (block.type === "multipleChoice") { kcs++; sectionKCs++; }
      if (block.type === "reflection") reflections++;
      if (["accordion", "flashcardDeck", "matching", "cardSort", "scenarioTree"].includes(block.type)) interactives++;
      if (block.type === "assessment") examQs = (block.questions || []).length;
    }
    sectionStats.push({ section: section.order, title: section.title.substring(0, 40), words: sectionWords, kcs: sectionKCs });
  }

  console.log("\n═══ CR-TMH601 REBUILD VALIDATION ═══");
  console.log(`Sections:          ${COURSE_DATA.sections.length}`);
  console.log(`Total blocks:      ${totalBlocks}`);
  console.log(`Knowledge checks:  ${kcs}`);
  console.log(`Reflections:       ${reflections}`);
  console.log(`Interactives:      ${interactives}`);
  console.log(`Final exam Qs:     ${examQs} (need ≥15)`);
  console.log(`References:        ${COURSE_DATA.references.length}`);
  console.log(`Text word count:   ~${totalWords}`);
  console.log(`CE requirement:    ${COURSE_DATA.ceHours * 6000} words`);
  console.log(`Word count status: ${totalWords >= COURSE_DATA.ceHours * 6000 ? "✓ PASS" : "✗ FAIL — add content"}`);
  console.log(`Exam status:       ${examQs >= 15 ? "✓ PASS" : "✗ FAIL — need ≥15 questions"}`);
  console.log("\n─── Per-Section Word Counts ───");
  sectionStats.forEach(s => {
    const flag = s.words < 2500 ? " ⚠ LOW" : "";
    console.log(`  S${s.section}: ${s.words}w  [${s.kcs} KCs]  ${s.title}${flag}`);
  });

  await mongoose.disconnect();
  console.log("\nDone. ✓");
}

main().catch(err => { console.error(err.message); process.exit(1); });
